--- a/runtime/pipeline/prefill_emitter.rs
+++ b/runtime/pipeline/prefill_emitter.rs
@@ -112,6 +112,22 @@ impl PrefillEmitter {
     fn emit_prefill_chunk(&mut self, chunk: PrefillChunk) {
+        // Emit chunked KV updates early to allow downstream decode to start
+        // if speculative policy signals likely-following tokens.
+        if self.config.chunked_emit && self.speculative_policy.should_emit_early(&chunk) {
+            self.pipeline.send_kv_updates(chunk.kv_updates());
+            self.pipeline.signal_decode_ready(chunk.last_token_index());
+        } else {
             self.buffer.push(chunk);
         }
     }
